  t.equal(c2, 1);
  t.deepEqual(tickValues(s1, c2), [0, 1]);

  const s2 = linear().domain([0, 10]);
  const c3 = tickCount(s2, 10, 3);
  t.equal(c3, 3);
  t.deepEqual(tickValues(s2, c3), [0, 5, 10]);
  t.equal(tickCount(s2, 10, 5), 3);

