  const c1 = tickCount(s1, 10, 1000 * 60 * 60 * 7);
  t.equal(c1, 4);
  t.deepEqual(
    tickValues(s1, c1).map(d => +d),
    [0, 6, 12, 18, 24].map(h => Date.UTC(2020, 0, 1, h))
  );

  t.end();
});

